def pop(self, elements=1):
    """
    Pops an abstract type from the output stack and returns its value.
    @param elements: number of stack elements to pop (default is 1)
    @return: the abstract type that has been popped from the output stack.
    """
    if self.outputStackTop < elements:
        raise IndexError("pop from empty stack")

    value = self.outputStack[self.outputStackTop - elements]

    # Clear the popped slot(s)
    for i in range(elements):
        self.outputStack[self.outputStackTop - elements + i] = 0

    self.outputStackTop -= elements

    return value

