def decodeOctets(i, bb, sb):
    """
    Decodes octets to characters using UTF-8 and appends the characters to a StringBuilder.
    @return the index to the next unchecked character in the string to decode
    """
    # Get the remaining bytes from the ByteBuffer
    remaining = bb.remaining()
    if remaining == 0:
        return i

    # Read bytes from the buffer
    bytes_list = []
    while bb.position() < bb.limit():
        bytes_list.append(bb.get())

    # Try to decode as UTF-8
    try:
        # Convert bytes to string using UTF-8
        decoded_str = bytes(bytes_list).decode('utf-8')
        sb.append(decoded_str)
        # Return the next unchecked character index
        return i + len(bytes_list)
    except UnicodeDecodeError:
        # If UTF-8 decoding fails, try to decode as much as possible
        for j in range(len(bytes_list), 0, -1):
            try:
                decoded_str = bytes(bytes_list[:j]).decode('utf-8')
                sb.append(decoded_str)
                return i + j
            except UnicodeDecodeError:
                continue
        # If still fails, append replacement character
        sb.append('\ufffd')
        return i + 1

