def decodeOctets(i, bb, sb):
    """
    Decodes octets to characters using UTF-8 and appends the characters to a StringBuilder.
    @return the index to the next unchecked character in the string to decode
    """
    # Get the remaining bytes from the ByteBuffer
    remaining = bb.remaining()
    if remaining == 0:
        return i

    # Read bytes from the buffer
    bytes_list = []
    pos = i
    while pos < len(bb.array()) and len(bytes_list) < remaining:
        byte_val = bb.array()[pos]
        if byte_val < 0:
            byte_val += 256
        bytes_list.append(byte_val)
        pos += 1

    # Try to decode as UTF-8
    try:
        # Convert bytes to bytes object
        byte_data = bytes(bytes_list)
        # Decode using UTF-8
        decoded_str = byte_data.decode('utf-8')
        # Append to StringBuilder (simulated with list in Python)
        sb.append(decoded_str)
        # Return the next unchecked character index
        return i + len(bytes_list)
    except UnicodeDecodeError:
        # If UTF-8 decoding fails, try to decode each byte individually
        for byte_val in bytes_list:
            try:
                char = bytes([byte_val]).decode('utf-8')
                sb.append(char)
            except UnicodeDecodeError:
                # Replace with replacement character if decoding fails
                sb.append('\ufffd')
        return i + len(bytes_list)

