        return i + len(bytes_list)
    except UnicodeDecodeError:
        # If UTF-8 decoding fails, try to decode as much as possible
        decoded_str = ""
        for byte in bytes_list:
            try:
                decoded_str += bytes([byte]).decode('utf-8')
            except UnicodeDecodeError:
                # For invalid UTF-8 sequences, use replacement character
                decoded_str += '\ufffd'
        sb.append(decoded_str)
        return i + len(bytes_list)

