    if size < 0:
        raise ValueError("Size must be non-negative")
    if self.length + size > len(self.data):
        new_capacity = max(len(self.data) * 2, self.length + size)
        new_data = bytearray(new_capacity)
        new_data[:self.length] = self.data[:self.length]
        self.data = new_data

