def nullSafeHashCode(array):
    if array is None:
        return 0
    INITIAL_HASH = 17
    MULTIPLIER = 31
    hash_code = INITIAL_HASH
    for element in array:
        if element is None:
            element_hash = 0
        else:
            element_hash = hash(element)
        hash_code = MULTIPLIER * hash_code + element_hash
    return hash_code

