import os
import java.io.File as JFile
import java.net.URL as JURL
import java.net.MalformedURLException

def addToClassPath(cpV, dir):
    """
    Add all the jar files in a dir to the classpath, represented as a Vector of URLs.
    """
    file_dir = JFile(dir)
    if file_dir.exists() and file_dir.isDirectory():
        for filename in os.listdir(dir):
            if filename.lower().endswith('.jar'):
                jar_path = os.path.join(dir, filename)
                try:
                    jar_url = JURL("file://" + jar_path)
                    cpV.add(jar_url)
                except MalformedURLException:
                    continue

