def addToClassPath(cpV, dir):
    import os
    import sys
    from java.io import File
    from java.net import URL, MalformedURLException

    try:
        dir_file = File(dir)
        if not dir_file.exists():
            return
        if not dir_file.isDirectory():
            return

        files = dir_file.listFiles()
        for f in files:
            if f.getName().endswith('.jar'):
                try:
                    url = f.toURI().toURL()
                    cpV.add(url)
                except MalformedURLException:
                    continue
    except Exception:
        pass

