import io

class OutputStreamWrapper:
    def __init__(self, output_stream=None):
        self.output_stream = output_stream if output_stream is not None else io.BytesIO()
        self.threshold = float('inf')
        self.written = 0
        self.threshold_exceeded = False

    def write(self, b):
        """
        Writes len(b) bytes from the specified byte array to this output stream.
        :param b: The array of bytes to be written.
        :raises IOError: if an error occurs.
        """
        if not isinstance(b, (bytes, bytearray, memoryview)):
            raise TypeError("b must be a bytes-like object")

        if self.written + len(b) > self.threshold:
            self.threshold_exceeded = True

        self.output_stream.write(b)
        self.written += len(b)
        self.check_threshold(len(b))

    def check_threshold(self, count):
        if self.written > self.threshold:
            self.threshold_exceeded = True
        else:
            self.threshold_exceeded = False

    def flush(self):
        self.output_stream.flush()

    def close(self):
        self.output_stream.close()

    def get_threshold(self):
        return self.threshold

    def get_byte_count(self):
        return self.written

    def is_threshold_exceeded(self):
        return self.threshold_exceeded

    def reset_byte_count(self):
        self.written = 0
        self.threshold_exceeded = False

    def get_stream(self):
        return self.output_stream

    def threshold_reached(self):
        return self.threshold_exceeded

