def identity(graph):
    """
    Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).

    Args:
        graph: The input graph

    Returns:
        A mapping from graph to graph where each vertex maps to itself
    """
    forward_mapping = {}
    backward_mapping = {}

    for vertex in graph.vertices():
        forward_mapping[vertex] = vertex
        backward_mapping[vertex] = vertex

    return {
        'forward_mapping': forward_mapping,
        'backward_mapping': backward_mapping,
        'graph': graph
    }

