import os
import atexit
import shutil


def forceDeleteOnExit(file):
    """
    Schedules a file to be deleted when the program exits. If file is a directory, delete it and all sub-directories.

    :param file: file or directory to delete, must not be None
    :raises TypeError: if the file is None
    :raises OSError: in case deletion is unsuccessful
    """
    if file is None:
        raise TypeError("file must not be None")

    def delete():
        try:
            if os.path.isdir(file):
                shutil.rmtree(file)
            else:
                os.remove(file)
        except Exception as e:
            # Silently ignore errors during cleanup to avoid interfering with program exit
            pass

    atexit.register(delete)

