import inspect
import weakref


class TypeVariable:
    def __init__(self, name: str, bound: Optional[Type] = None):
        self.name = name
        self.bound = bound

    def __repr__(self):
        return f"TypeVariable({self.name}, bound={self.bound})"


class GenericType:
    def __init__(self, origin: Type, args: List[Type]):
        self.origin = origin
        self.args = args

    def __repr__(self):
        return f"GenericType(origin={self.origin}, args={self.args})}


class TypeResolver:
    def __init__(self):
        self.typeVariableCache = weakref.WeakKeyDictionary()
        self.cacheEnabled = True

    def disableCache(self):
        self.cacheEnabled = False
        return self

    def resolveArgument(self, initialType, targetType):
        if isinstance(initialType, type):
            return self.resolveArgument(Type(initialType), targetType)
        elif isinstance(initialType, Type):
            return self.resolveArgument(initialType.type, targetType)
        else:
