def diffStructure(current_mappings, history_mappings):
    """
    Returns mappings with fields that do not exist in the input mappings.
    The input mappings should be history mapping from current index.
    Do not return _source config to avoid current index update conflict.

    Args:
        current_mappings: Current mappings structure
        history_mappings: History mappings structure from current index

    Returns:
        Mappings containing only the new fields that don't exist in history_mappings
    """
    if not current_mappings or not history_mappings:
        return current_mappings or {}

    result = {}

    # Process properties if they exist in both mappings
    current_properties = current_mappings.get("properties", {})
    history_properties = history_mappings.get("properties", {})

    # Find new fields in current properties that don't exist in history properties
    new_properties = {}
    for field_name, field_def in current_properties.items():
        if field_name not in history_properties:
            new_properties[field_name] = field_def

    if new_properties:
        result["properties"] = new_properties

    # Process nested mappings (like object type fields)
    for field_name, field_def in current_properties.items():
        if field_name in history_properties:
            # Check if nested structure has new fields
            current_type = field_def.get("type", "object")
            history_type = history_properties.get(field_name, {}).get("type", "object")

            if current_type == "object" and history_type == "object":
                # Recursively check nested properties
                nested_current = field_def.get("properties", {})
                nested_history = history_properties.get(field_name, {}).get("properties", {})

                nested_diff = {}
                for nested_field, nested_def in nested_current.items():
                    if nested_field not in nested_history:
                        nested_diff[nested_field] = nested_def

                if nested_diff:
                    if "properties" not in result:
                        result["properties"] = {}
                    result["properties"][field_name] = field_def.copy()
                    result["properties"][field_name]["properties"] = nested_diff

    # Process meta fields if they exist (excluding _source)
    meta_fields = ["_all", "_meta", "dynamic_templates"]
    for meta_field in meta_fields:
        if meta_field in current_mappings and meta_field not in history_mappings:
            result[meta_field] = current_mappings[meta_field]

    # Handle dynamic_templates specifically
    if "dynamic_templates" in current_mappings:
        current_dt = current_mappings["dynamic_templates"]
        history_dt = history_mappings.get("dynamic_templates", [])

        # Compare dynamic templates by their content
        new_dt = []
        for dt_item in current_dt:
            if dt_item not in history_dt:
                new_dt.append(dt_item)

        if new_dt:
            result["dynamic_templates"] = new_dt

    return result

