                result[field_name] = {
                    'type': 'object',
                    'properties': diffStructure(
                        {'properties': field_def.get('properties', {})},
                        {'properties': {}}
                    ).get('properties', {})
                }
            else:
                result[field_name] = field_def

    # Process nested objects recursively
    for field_name, field_def in current_properties.items():
        if field_name in history_properties:
            current_nested = field_def.get('properties', {})
            history_nested = history_properties[field_name].get('properties', {})

            if current_nested or history_nested:
                nested_diff = diffStructure(
                    {'properties': current_nested},
                    {'properties': history_nested}
                )

                if nested_diff.get('properties'):
                    if field_name not in result:
                        result[field_name] = field_def.copy()
                    result[field_name]['properties'] = nested_diff['properties']

    # Handle other top-level keys (excluding _source)
    for key, value in current_mappings.items():
        if key not in ['properties', '_source']:
            if key not in history_mappings or history_mappings[key] != value:
                result[key] = value

    return result

