def computeUTF8Size(str, index, len):
    if str is None:
        raise ValueError("Input string cannot be None")
    if index < 0 or len < 0 or index + len > len(str):
        raise ValueError("Invalid index or length")

    size = 0
    end = index + len

    i = index
    while i < end:
        ch = ord(str[i])

        if ch < 0x80:
            size += 1
        elif ch < 0x800:
            size += 2
        elif ch < 0xd800 or ch >= 0xe000:
            size += 3
        else:
            # Handle surrogate pair
            if i + 1 >= end:
                size += 3
            else:
                ch2 = ord(str[i + 1])
                if ch2 >= 0xdc00 and ch2 < 0xe000:
                    size += 4
                    i += 1
                else:
                    size += 3
        i += 1

    return size

