def appendDetail(buffer, fieldName, array, fullDetail=None):
    """
    Append to the buffer the detail of an int array.

    Args:
        buffer: The buffer to populate
        fieldName: The field name (typically not used as already appended)
        array: The array to add to the buffer, not null
        fullDetail: Whether to use full detail
    """
    if array is None:
        return

    if not isinstance(array, list):
        return

    if len(array) == 0:
        return

    # Apply default full detail if not specified
    if fullDetail is None:
        fullDetail = True

    # Process each element in the array
    for i, item in enumerate(array):
        # Add separator between elements (except before the first element)
        if i > 0:
            buffer.append(", ")

        # Append the detail of the current element
        if isinstance(item, int):
            buffer.append(str(item))
        elif isinstance(item, list):
            # Recursively handle nested arrays
            appendDetail(buffer, fieldName, item, fullDetail)
        else:
            buffer.append(str(item))

