from typing import Tuple

class Box2D:
    def __init__(self, x_min: float, y_min: float, x_max: float, y_max: float):
        self.x_min = x_min
        self.y_min = y_min
        self.x_max = x_max
        self.y_max = y_max

def splitAlongXAxis(box: Box2D) -> Tuple[Box2D, Box2D]:
    x_mid = (box.x_min + box.x_max) / 2
    left_box = Box2D(box.x_min, box.y_min, x_mid, box.y_max)
    right_box = Box2D(x_mid, box.y_min, box.x_max, box.y_max)
    return (left_box, right_box)

