    """
    Create a string supplier which returns unique strings. The returned strings are simply integers starting from start.
    @param start where to start the sequence
    @return a string supplier
    """
    current = start

    def supplier():
        nonlocal current
        result = str(current)
        current += 1
        return result

    return supplier

