    """Clear and fill the buffer of this ClassFileBuffer with the supplied byte stream. The read pointer is reset to the start of the byte array."""
    if isinstance(data, bytes):
        self.buffer = bytearray(data)
        self.size = len(data)
        self.pointer = 0
    elif hasattr(data, 'read'):
        self.buffer = bytearray(data.read())
        self.size = len(self.buffer)
        self.pointer = 0
    else:
        raise TypeError("data must be bytes or a file-like object with read() method")

def write(b):
    global writer, encoding, buf
    try:
        if encoding:
            decoded_str = b.decode(encoding)
        else:
            decoded_str = b.decode()
        writer.write(decoded_str)
    except (UnicodeDecodeError, AttributeError):
        # If b is not bytes, try to handle as string
        if isinstance(b, bytes):
            decoded_str = b.decode('utf-8')
            writer.write(decoded_str)
        else:
            writer.write(str(b))

