def readString(buffer, pos):
    # Read length as varint
    length = 0
    shift = 0
    while True:
        if pos >= len(buffer):
            raise EOFError("Buffer underflow")
        byte = buffer[pos]
        pos += 1
        length |= (byte & 0x7F) << shift
        if (byte & 0x80) == 0:
            break
        shift += 7
        if shift >= 32:
            raise ValueError("Varint too long")

    # Check if we have enough bytes for the string
    if pos + length > len(buffer):
        raise EOFError("Buffer underflow")

    # Extract and decode the string
    string_bytes = buffer[pos:pos + length]
    pos += length

    try:
        return string_bytes.decode('utf-8'), pos
    except UnicodeDecodeError:
        # Fallback to latin-1 which never fails
        return string_bytes.decode('latin-1'), pos

