def toByteArray(self):
    if self.head is None:
        return b''

    result = bytearray(self.size)
    pos = 0
    current = self.head

    while current is not None:
        # Copy bytes from the current buffer
        buffer_data = current.data if hasattr(current, 'data') else current
        if isinstance(buffer_data, bytes):
            result[pos:pos + len(buffer_data)] = buffer_data
            pos += len(buffer_data)
        elif isinstance(buffer_data, bytearray):
            result[pos:pos + len(buffer_data)] = buffer_data
            pos += len(buffer_data)
        else:
            # Assume it's a list or other iterable of bytes
            for i, byte in enumerate(buffer_data):
                result[pos + i] = byte
            pos += len(buffer_data)

        current = current.next if hasattr(current, 'next') else None

    return bytes(result)

