def deleteAny(inString, charsToDelete):
    """
    Delete any character in a given String.
    @param inString the original String
    @param charsToDelete a set of characters to delete. E.g. "az\n" will delete 'a's, 'z's and new lines.
    @return the resulting String
    """
    if inString is None:
        return None
    if charsToDelete is None:
        return inString

    # Create a set of characters to delete for O(1) lookup
    delete_set = set(charsToDelete)

    # Build the result string by excluding characters in the delete set
    result = ''.join(char for char in inString if char not in delete_set)

    return result

