import enum
from typing import Any, Optional
from dataclasses import dataclass
from enum import Enum


class TRANSPORT(Enum):
    UNDEFINED = "undefined"
    WEBSOCKET = "websocket"
    LONG_POLLING = "long-polling"
    SERVER_SENT_EVENTS = "server-sent-events"
    STREAMING = "streaming"
    JSONP = "jsonp"
    AJAX = "ajax"


@dataclass
class AtmosphereResource:
    transport_value: str = TRANSPORT.UNDEFINED.value

    def transport(self) -> TRANSPORT:
        try:
            return TRANSPORT(self.transport_value)
        except ValueError:
            return TRANSPORT.UNDEFINED


class Action(Enum):
    CONTINUE = "CONTINUE"


class AtmosphereResourceLifecycleInterceptor:
    def __init__(self, force: bool = False):
        self.force = force
        self.method: Optional[str] = None
        self.timeout_in_seconds: Optional[int] = None
        self.logger = None
        self.timeout_in_milli: int = 0

    def configure(self, config: Any) -> None:
        pass

    def post_inspect(self, r: AtmosphereResource) -> None:
        pass

    def on_broadcast(self, event: Any) -> None:
        pass

    def inspect(self, r: AtmosphereResource) -> Action:
        transport = r.transport()
        if transport == TRANSPORT.WEBSOCKET:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.LONG_POLLING:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.SERVER_SENT_EVENTS:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.STREAMING:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.JSONP:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.AJAX:
            if self.force or not r.is_suspended():
                r.suspend()
        elif transport == TRANSPORT.UNDEFINED:
            pass
        return Action.CONTINUE

    def method(self, method: str) -> None:
        self.method = method

    def timeout_in_seconds(self, timeout_in_seconds: int) -> None:
        self.timeout_in_seconds = timeout_in_seconds

    def destroy(self) -> None:
        pass

    def __str__(self) -> str:
        return f"Method: {self.method}, Timeout: {self.timeout_in_seconds}"


def inspect(r: AtmosphereResource) -> Action:
    interceptor = AtmosphereResourceLifecycleInterceptor()
    return interceptor.inspect(r)

