def reload(buckets_by_label, labels, min_label):
    # Move all vertices from the bucket with label min_label to the bucket with label 0
    if min_label < len(buckets_by_label) and buckets_by_label[min_label]:
        vertices_to_move = buckets_by_label[min_label][:]
        buckets_by_label[0].extend(vertices_to_move)

        # Update labels for moved vertices to 0
        for vertex in vertices_to_move:
            labels[vertex] = 0

        # Clear the bucket with label min_label
        buckets_by_label[min_label].clear()

