    if array is None:
        buffer.append("null")
        return

    buffer.append("[")
    for i, item in enumerate(array):
        if i > 0:
            buffer.append(", ")
        if isinstance(item, (list, tuple)):
            appendDetail(buffer, fieldName, item)
        elif isinstance(item, bytes):
            buffer.append(str(list(item)))
        elif isinstance(item, (int, float, bool, str)):
            buffer.append(str(item))
        elif item is None:
            buffer.append("null")
        else:
            buffer.append(repr(item))
    buffer.append("]")

