    """
    Check whether the existed buckets are the same as the buckets.

    Args:
        existed_buckets: List of existing bucket objects or values
        buckets: List of new bucket objects or values to compare with

    Returns:
        bool: True if the buckets are the same, False otherwise
    """
    if existed_buckets is None and buckets is None:
        return True
    if existed_buckets is None or buckets is None:
        return False
    if len(existed_buckets) != len(buckets):
        return False

    # Compare bucket by bucket
    for i in range(len(existed_buckets)):
        if isinstance(existed_buckets[i], dict) and isinstance(buckets[i], dict):
            # If buckets are dictionaries, compare their contents
            if existed_buckets[i] != buckets[i]:
                return False
        elif hasattr(existed_buckets[i], '__dict__') and hasattr(buckets[i], '__dict__'):
            # If buckets are objects, compare their attributes
            if (not hasattr(existed_buckets[i], '__eq__') or 
                not existed_buckets[i].__eq__(buckets[i])):
                # Fallback to comparing attributes manually
                if vars(existed_buckets[i]) != vars(buckets[i]):
                    return False
        else:
            # Direct comparison for primitive types
            if existed_buckets[i] != buckets[i]:
                return False

    return True

