def findClass(className):
    """
    Find class given class name.
    @param className class name, may not be null.
    @return class, will not be null.
    @throws ClassNotFoundException thrown if class can not be found.
    """
    try:
        # Try to get the class from built-in modules first
        if className in globals():
            return globals()[className]

        # Try to import the class dynamically
        parts = className.split('.')
        module_name = '.'.join(parts[:-1]) if len(parts) > 1 else None
        class_name = parts[-1]

        if module_name:
            module = __import__(module_name, fromlist=[class_name])
            return getattr(module, class_name)
        else:
            return __import__(className)
    except (ImportError, AttributeError):
        raise ClassNotFoundException(f"Class {className} not found")

