def buildSequenceRanges(minSequence, maxSequence, SEQUENCE_RANGE_BATCH_SIZE):
    if minSequence > maxSequence:
        return []

    ranges = []
    current_min = minSequence

    while current_min <= maxSequence:
        current_max = min(current_min + SEQUENCE_RANGE_BATCH_SIZE - 1, maxSequence)
        ranges.append((current_min, current_max))
        current_min = current_max + 1

    return ranges

