def stripFilenameExtension(path):
    """
    Strip the filename extension from the given path, e.g. "mypath/myfile.txt" -> "mypath/myfile".
    @param path the file path (may be None)
    @return the path with stripped filename extension, or None if none
    """
    if path is None:
        return None

    # Find the last dot that separates the extension
    last_dot_index = path.rfind('.')

    # If no dot found, return the original path
    if last_dot_index == -1:
        return path

    # Find the last path separator to ensure we're only removing the extension from the filename
    last_separator_index = max(path.rfind('/'), path.rfind('\\'))

    # If the dot is before the last separator, or there's no separator, strip the extension
    if last_dot_index > last_separator_index:
        return path[:last_dot_index]
    else:
        return path

