def toCharacterObject(ch):
    """
    Converts the character to a Character object.
    For ASCII 7 bit characters, this uses a cache that will return the same Character object each time.

    Args:
        ch: The character to convert

    Returns:
        A Character object of the specified character
    """
    if isinstance(ch, str) and len(ch) == 1:
        ch = ch[0]

    if isinstance(ch, int):
        ch = chr(ch)

    if not isinstance(ch, str) or len(ch) != 1:
        raise ValueError("Input must be a single character")

    # For ASCII characters (0-127), use a cache
    if ord(ch) < 128:
        if not hasattr(toCharacterObject, '_ascii_cache'):
            toCharacterObject._ascii_cache = [chr(i) for i in range(128)]
        return toCharacterObject._ascii_cache[ord(ch)]
    else:
        # For non-ASCII characters, return a new string (acting as Character object)
        return ch

