def decide(event):
    """
    Returns Filter.NEUTRAL if there is no string match.
    """
    message = event.getMessage()
    if not hasattr(event, 'stringToMatch'):
        return Filter.NEUTRAL
    string_to_match = event.stringToMatch
    if string_to_match is None:
        return Filter.NEUTRAL
    if string_to_match in message:
        if hasattr(event, 'acceptOnMatch') and event.acceptOnMatch:
            return Filter.ACCEPT
        else:
            return Filter.DENY
    else:
        return Filter.NEUTRAL

