TOLERANCE_DOUBLE_COMPARATOR = 1e-9

def equals(p1, p2):
    """
    Compare two points for equality using tolerance 1e-9.
    @param p1 the first point
    @param p2 the second point
    @return whether the two points are equal or not
    """
    return isclose(p1[0], p2[0], abs_tol=TOLERANCE_DOUBLE_COMPARATOR) and \
           isclose(p1[1], p2[1], abs_tol=TOLERANCE_DOUBLE_COMPARATOR)

