def applyRelativePath(path, relativePath):
    FOLDER_SEPARATOR = "/"
    if path is None:
        path = ""
    if relativePath is None:
        relativePath = ""

    if relativePath == "":
        return path

    # Get the directory part of the path (before the last FOLDER_SEPARATOR)
    if FOLDER_SEPARATOR in path:
        path_before_folder = path.rsplit(FOLDER_SEPARATOR, 1)[0]
        if path_before_folder:
            path_before_folder += FOLDER_SEPARATOR
    else:
        path_before_folder = ""

    # Combine the directory part with the relative path
    result = path_before_folder + relativePath

    # Clean up the path (resolve . and ..)
    result = cleanPath(result)

    return result


def cleanPath(path):
    if path is None:
        return None

    # Replace backslashes with forward slashes for consistency
    path = path.replace("\\", "/")

    # Split the path into parts
    parts = path.split("/")
    result = []

    for part in parts:
        if part == "" or part == ".":
            continue
        elif part == "..":
            if result:
                result.pop()
        else:
            result.append(part)

    # Reconstruct the path
    result_path = "/".join(result)

    # Add leading slash if the original path had one
    if path.startswith("/"):
        result_path = "/" + result_path

    return result_path

