def indexOfExtension(filename):
    if filename is None:
        return -1

    # Find the last occurrence of any directory separator
    last_separator = -1
    for sep in ['/', '\\']:
        idx = filename.rfind(sep)
        if idx > last_separator:
            last_separator = idx

    # Find the last dot
    last_dot = filename.rfind('.')

    # If there's no dot, return -1
    if last_dot == -1:
        return -1

    # If the dot is before the last separator, return -1
    if last_separator >= last_dot:
        return -1

    return last_dot

