    if self.current is None or self.prev is None:
        return None

    # If either node is virtual, get its real counterpart
    current_real = self.current.getRealCounterpart() if hasattr(self.current, 'getRealCounterpart') else self.current
    prev_real = self.prev.getRealCounterpart() if hasattr(self.prev, 'getRealCounterpart') else self.prev

    # Find the edge connecting prev_real to current_real
    if hasattr(self.graph, 'getEdge'):
        edge = self.graph.getEdge(prev_real, current_real)
        if edge is not None:
            return edge

    # If direct edge lookup fails, search through edges
    if hasattr(self.graph, 'edges'):
        for edge in self.graph.edges:
            source = edge.source if hasattr(edge, 'source') else edge[0]
            target = edge.target if hasattr(edge, 'target') else edge[1]

            if (source == prev_real and target == current_real) or \
               (target == prev_real and source == current_real):
                return edge

    return None

