def substringMatch(str, index, substring):
    """
    Returns True if the given string matches the given substring at the given index, False otherwise.
    @param str the original string (or StringBuilder)
    @param index the index in the original string to start matching against
    @param substring the substring to match at the given index
    @return True if the given string matches the given substring at the given index, False otherwise.
    """
    if index < 0 or index + len(substring) > len(str):
        return False
    return str[index:index + len(substring)] == substring

