def readTag(buffer, TAG_TYPE_BITS):
    """
    Attempt to read a field tag, returning zero if we have reached EOF. Protocol message parsers use this to read tags, since a protocol message may legally end wherever a tag occurs, and zero is not a valid tag number.
    """
    try:
        # Read raw varint32 from buffer
        value = 0
        shift = 0
        while True:
            if shift >= 32:
                raise IOError("Too many bytes when reading varint")
            byte = buffer.read(1)
            if not byte:
                return 0  # EOF reached
            b = ord(byte)
            value |= (b & 0x7F) << shift
            if (b & 0x80) == 0:
                break
            shift += 7

        # Check if tag is valid after logical shift right by TAG_TYPE_BITS
        if (value >> TAG_TYPE_BITS) == 0:
            raise ValueError("Invalid tag: zero after logical shift right by TAG_TYPE_BITS")

        return value
    except Exception:
        raise

